def _validate():
    """Catch data mistakes without rendering pages or changing the workspace."""
    assert len(DEPTH_DIAGRAMS) == 5
    assert len({d['id'] for d in DEPTH_DIAGRAMS}) == 5
    assert len({d['chapter'] for d in DEPTH_DIAGRAMS}) == 5
    for d in DEPTH_DIAGRAMS:
        node_ids = {n['id'] for n in d['nodes']}
        edge_ids = {e['id'] for e in d['edges']}
        assert 3 <= len(node_ids) <= 5
        assert 5 <= len(d['steps']) <= 7
        assert len(edge_ids) == len(d['edges'])
        assert all(e['from'] in node_ids and e['to'] in node_ids for e in d['edges'])
        for step in d['steps']:
            assert set(step['states']) == node_ids
            assert set(step['focus']) <= node_ids
            assert set(step['active']) <= edge_ids
            assert len(step['fields']) == len(step['bands']) >= 2
            assert all(all(f[k] for k in ('name', 'before', 'after', 'why'))
                       for f in step['fields'])


_validate()
